// Augments the `CloudflareEnv` interface (bindings live in
// worker-configuration.d.ts, regenerated by `npm run cf-typegen` — see
// wrangler.jsonc) with secrets/plain env vars that aren't Cloudflare
// bindings, so they aren't picked up by `wrangler types`. Set locally in
// .dev.vars (gitignored) and in production via `wrangler secret put`.
// See .env.example for the full list.
interface CloudflareEnv {
  BETTER_AUTH_SECRET: string;
  /** Origin better-auth builds magic-link callback URLs from. */
  BETTER_AUTH_URL?: string;
  /** Origin used for portal/event links inside outgoing email; falls back to
   * BETTER_AUTH_URL. */
  APP_URL?: string;
  /**
   * Comma-separated list of email addresses promoted to admin when they sign
   * in (decisions.md D-043, src/domain/team.ts). Case-insensitive and
   * whitespace tolerant. Optional, and the only automatic route to admin:
   * leave it unset and the first admin is promoted by hand instead
   * (docs/deploying.md §7).
   */
  ADMIN_EMAILS?: string;
  /** Temporary evaluation access. The feature fails closed unless all five
   * values are present, the token is high entropy, and the expiry is future. */
  EVALUATION_ACCESS_TOKEN?: string;
  EVALUATION_ACCESS_EXPIRES_AT?: string;
  EVALUATION_ORGANIZER_EMAIL?: string;
  EVALUATION_REVIEWER_EMAIL?: string;
  EVALUATION_SPEAKER_EMAIL?: string;
  SENDGRID_API_KEY?: string;
  /** From identity on every outgoing email (src/lib/email.ts). The address
   * also becomes the calendar invite's ORGANIZER, so it must be a real,
   * verified sending address in production. */
  EMAIL_FROM_NAME?: string;
  EMAIL_FROM_ADDRESS?: string;
  /**
   * Airtable personal access token for the one-way sync (decisions.md D-036,
   * docs/airtable-sync.md). Production: `wrangler secret put AIRTABLE_API_KEY`
   * and `wrangler secret put AIRTABLE_BASE_ID` — both are secrets so nothing
   * account-specific is committed. Local dev reads both from `.dev.vars`.
   * Missing either one makes the sync no-op with a log line rather than
   * throwing.
   */
  AIRTABLE_API_KEY?: string;
  AIRTABLE_BASE_ID?: string;
}
